/*
 * XR8Tracker — tracks phones showing the dashed tracking border
 * (public/phone/js/borderPattern.js) with the 8th Wall engine, using a
 * static laptop webcam.
 *
 * Each phone screen is covered by two 3:4 image targets ("top" and "bottom",
 * generated by server.js for the phone's CSS screen size). 8th Wall reports a
 * 3D pose per found target; we map any phone-screen point (CSS px) onto that
 * plane, average over the targets that are currently found, and project it
 * into canvas pixels with the camera intrinsics. The white middle of the
 * screen has no features in the target image, so whatever the phone shows
 * there does not take part in recognition.
 *
 * Usage:
 *   XR8Tracker.start({ canvas, onFrame, onStatus, onEvent })
 *   XR8Tracker.setPhones([{ id, screenW, screenH }])
 *
 *   onFrame({ phones, camW, camH })  — every camera frame
 *     phones[id] = { id, parts: ['top', …], screenW, screenH,
 *                    project(u, v) → {x, y} canvas CSS px }
 *   onStatus(text, level)            — 'loading' | 'searching' | 'tracking' | 'error'
 *   onEvent(name, detail)            — raw engine events (for the test page)
 */
window.XR8Tracker = (function () {
  'use strict';

  var _opts     = null;
  var _canvas   = null;
  var _phones   = {};  // id → {id, screenW, screenH}
  var _targets  = {};  // target name → {phoneId, region}
  var _found    = {};  // target name → latest engine detail
  var _camera   = null; // {position, rotation, intrinsics}
  var _running  = false;
  var _configSeq = 0;

  function emit(name, detail) {
    if (_opts && _opts.onEvent) _opts.onEvent(name, detail);
  }
  function status(text, level) {
    if (_opts && _opts.onStatus) _opts.onStatus(text, level);
  }

  /* ── Math helpers ────────────────────────────────────────────────── */
  function quatRotate(q, v) {
    // v' = v + 2w(q×v) + 2 q×(q×v)
    var cx = q.y * v.z - q.z * v.y, cy = q.z * v.x - q.x * v.z, cz = q.x * v.y - q.y * v.x;
    var ccx = q.y * cz - q.z * cy, ccy = q.z * cx - q.x * cz, ccz = q.x * cy - q.y * cx;
    return {
      x: v.x + 2 * (q.w * cx + ccx),
      y: v.y + 2 * (q.w * cy + ccy),
      z: v.z + 2 * (q.w * cz + ccz)
    };
  }

  // World point → canvas CSS px (camera looks down −Z, intrinsics are a
  // column-major GL projection matrix for the canvas).
  function projectWorld(p) {
    if (!_camera || !_camera.intrinsics) return null;
    var c = _camera, m = c.intrinsics;
    var rel = { x: p.x - c.position.x, y: p.y - c.position.y, z: p.z - c.position.z };
    var q = c.rotation;
    var v = quatRotate({ x: -q.x, y: -q.y, z: -q.z, w: q.w }, rel);
    var cx = m[0] * v.x + m[4] * v.y + m[8]  * v.z + m[12];
    var cy = m[1] * v.x + m[5] * v.y + m[9]  * v.z + m[13];
    var cw = m[3] * v.x + m[7] * v.y + m[11] * v.z + m[15];
    if (Math.abs(cw) < 1e-9) return null;
    return {
      x: (cx / cw + 1) / 2 * _canvas.clientWidth,
      y: (1 - cy / cw) / 2 * _canvas.clientHeight
    };
  }

  // Phone-screen point (CSS px) → world point, using one found target.
  function screenToWorld(detail, region, u, v) {
    var sw = (detail.scaledWidth || 0.75) * detail.scale;
    var sh = (detail.scaledHeight || 1) * detail.scale;
    var local = {
      x: ((u - region.x) / region.w - 0.5) * sw,
      y: (0.5 - (v - region.y) / region.h) * sh,
      z: 0
    };
    var r = quatRotate(detail.rotation, local);
    return { x: detail.position.x + r.x, y: detail.position.y + r.y, z: detail.position.z + r.z };
  }

  /* ── Targets ─────────────────────────────────────────────────────── */
  function setPhones(list) {
    var next = {};
    (list || []).forEach(function (p) {
      if (p && p.screenW && p.screenH) next[p.id] = { id: p.id, screenW: p.screenW, screenH: p.screenH };
    });
    if (JSON.stringify(next) === JSON.stringify(_phones)) return;
    _phones = next;
    if (_running) loadTargets();
  }

  function loadTargets() {
    var seq = ++_configSeq;
    var ids = Object.keys(_phones);
    Promise.all(ids.map(function (id) {
      var p = _phones[id];
      return fetch('/xr8-targets/' + p.screenW + 'x' + p.screenH + '/targets.json')
        .then(function (r) { return r.json(); })
        .then(function (list) {
          return list.map(function (t) {
            // Unique name + image URL per phone (the engine de-duplicates by imagePath)
            return Object.assign({}, t, {
              name: 'phone' + id + '-' + t.metadata.region.part,
              imagePath: t.imagePath + '?phone=' + id,
              metadata: null,
              _phoneId: Number(id),
              _region: t.metadata.region
            });
          });
        });
    })).then(function (lists) {
      if (seq !== _configSeq) return;
      var all = [].concat.apply([], lists);
      _targets = {};
      all.forEach(function (t) { _targets[t.name] = { phoneId: t._phoneId, region: t._region }; });
      Object.keys(_found).forEach(function (n) { if (!_targets[n]) delete _found[n]; });
      XR8.XrController.configure({
        imageTargetData: all.map(function (t) {
          var c = Object.assign({}, t);
          delete c._phoneId; delete c._region;
          return c;
        })
      });
      emit('targets', { names: Object.keys(_targets) });
      status(all.length ? 'Loading targets' : 'Waiting for phone', all.length ? 'loading' : 'searching');
    }).catch(function (err) {
      console.error('[XR8Tracker] target load failed', err);
      status('Target load failed', 'error');
    });
  }

  /* ── Per-frame output ─────────────────────────────────────────────── */
  function buildPhones() {
    var byPhone = {};
    Object.keys(_found).forEach(function (name) {
      var t = _targets[name];
      if (!t || !_phones[t.phoneId]) return;
      (byPhone[t.phoneId] = byPhone[t.phoneId] || []).push({ detail: _found[name], region: t.region });
    });

    var out = {};
    Object.keys(byPhone).forEach(function (id) {
      var hits = byPhone[id];
      var phone = _phones[id];
      out[id] = {
        id: Number(id),
        parts: hits.map(function (h) { return h.region.part; }),
        screenW: phone.screenW,
        screenH: phone.screenH,
        project: function (u, v) {
          var sum = { x: 0, y: 0, z: 0 };
          hits.forEach(function (h) {
            var w = screenToWorld(h.detail, h.region, u, v);
            sum.x += w.x; sum.y += w.y; sum.z += w.z;
          });
          var n = hits.length;
          return projectWorld({ x: sum.x / n, y: sum.y / n, z: sum.z / n });
        },
        // Outline of a single target region (for debugging overlays)
        projectRegion: function (part) {
          var h = hits.filter(function (x) { return x.region.part === part; })[0];
          if (!h) return null;
          var r = h.region;
          return [[r.x, r.y], [r.x + r.w, r.y], [r.x + r.w, r.y + r.h], [r.x, r.y + r.h]]
            .map(function (p) { return projectWorld(screenToWorld(h.detail, r, p[0], p[1])); });
        }
      };
    });
    return out;
  }

  /* ── Engine setup ─────────────────────────────────────────────────── */
  function onImage(kind) {
    return function (e) {
      var d = e.detail;
      if (kind === 'lost') delete _found[d.name];
      else _found[d.name] = d;
      emit('image' + kind, d);
    };
  }

  function pipelineModule() {
    var lastLevel = null;
    return {
      name: 'reverseprojection-tracker',
      onStart: function () {
        _running = true;
        emit('started', {});
        loadTargets();
      },
      onCameraStatusChange: function (e) {
        emit('camera', e);
        if (e.status === 'failed') status('Camera failed', 'error');
      },
      onException: function (err) {
        console.error('[XR8Tracker]', err);
        emit('exception', { message: String(err && err.message || err) });
        status('8th Wall error', 'error');
      },
      onUpdate: function (args) {
        var reality = args.processCpuResult && args.processCpuResult.reality;
        if (!reality) return;
        _camera = { position: reality.position, rotation: reality.rotation, intrinsics: reality.intrinsics };
        var phones = buildPhones();
        var level = Object.keys(phones).length ? 'tracking'
          : Object.keys(_targets).length ? 'searching' : null;
        if (level && level !== lastLevel) {
          status(level === 'tracking' ? 'Tracking' : 'Searching', level);
        }
        lastLevel = level;
        if (_opts.onFrame) {
          _opts.onFrame({ phones: phones, camW: _canvas.clientWidth, camH: _canvas.clientHeight });
        }
      },
      listeners: [
        { event: 'reality.imageloading',  process: function (e) { emit('imageloading', e.detail); } },
        { event: 'reality.imagescanning', process: function (e) { emit('imagescanning', e.detail); status('Searching', 'searching'); } },
        { event: 'reality.imagefound',    process: onImage('found') },
        { event: 'reality.imageupdated',  process: onImage('updated') },
        { event: 'reality.imagelost',     process: onImage('lost') }
      ]
    };
  }

  function sizeCanvas() {
    var dpr = window.devicePixelRatio || 1;
    var w = Math.round(_canvas.clientWidth * dpr), h = Math.round(_canvas.clientHeight * dpr);
    if (w && h && (_canvas.width !== w || _canvas.height !== h)) {
      _canvas.width = w;
      _canvas.height = h;
    }
  }

  function start(opts) {
    _opts = opts || {};
    _canvas = _opts.canvas;
    status('Loading 8th Wall', 'loading');

    var go = function () {
      sizeCanvas();
      window.addEventListener('resize', sizeCanvas);
      XR8.XrController.configure({
        // Required for camera tracking on a laptop; also what we want: the
        // webcam is static, only the phone moves.
        disableWorldTracking: true,
        imageTargetData: []
      });
      XR8.addCameraPipelineModules([
        XR8.GlTextureRenderer.pipelineModule(),
        XR8.XrController.pipelineModule(),
        pipelineModule()
      ]);
      XR8.run({
        canvas: _canvas,
        allowedDevices: XR8.XrConfig.device().ANY,
        cameraConfig: { direction: XR8.XrConfig.camera().BACK }
      });
    };
    if (window.XR8) go();
    else window.addEventListener('xrloaded', go);
  }

  return { start: start, setPhones: setPhones };
})();
